import re

class WalletValidator:
    """
    A class to validate wallet addresses for a decentralized launchpad.
    """

    def __init__(self, supported_chains):
        """
        Initialize the WalletValidator with supported blockchain configurations.

        :param supported_chains: A dictionary containing chain names and their address validation regex patterns.
        Example:
        {
            "Ethereum": r"^0x[a-fA-F0-9]{40}$",
            "BinanceSmartChain": r"^0x[a-fA-F0-9]{40}$",
            "Solana": r"^[1-9A-HJ-NP-Za-km-z]{32,44}$"
        }
        """
        self.supported_chains = supported_chains

    def validate_wallet(self, chain_name, wallet_address):
        """
        Validate a wallet address for a specific blockchain.

        :param chain_name: The name of the blockchain (e.g., "Ethereum", "Solana").
        :param wallet_address: The wallet address to validate.
        :return: True if the wallet address is valid, False otherwise.
        """
        if chain_name not in self.supported_chains:
            raise ValueError(f"Unsupported chain: {chain_name}")

        pattern = self.supported_chains[chain_name]
        if re.match(pattern, wallet_address):
            return True
        return False


